// 1) Rola i uprawnienia (w produkcji: z SSO). 2) Maskowanie danych osobowych przed modelem.
const body = $input.first().json.body || {};
const user = String(body.user || 'anonim');
const dept = String(body.dept || 'wspolne');
const text = String(body.message || '');

const allowed = { sprzedaz:['wspolne','sprzedaz'], obsluga:['wspolne','obsluga'], ksiegowosc:['wspolne','ksiegowosc'], biuro:['wspolne','biuro'], zarzad:['wspolne','sprzedaz','obsluga','ksiegowosc','biuro','zarzad'] };
const depts = allowed[dept] || ['wspolne'];

const rules = [ ['EMAIL', /[\w.+-]+@[\w-]+\.[\w.-]+/g], ['PESEL', /\b\d{11}\b/g], ['TELEFON', /(?:\+48[\s-]?)?\b\d{3}[\s-]\d{3}[\s-]\d{3}\b|\b\d{9}\b/g], ['OSOBA', /\b(?:Pan|Pani)\s+[A-ZĄĆĘŁŃÓŚŹŻ][a-ząćęłńóśźż]+\s+[A-ZĄĆĘŁŃÓŚŹŻ][a-ząćęłńóśźż]+/g] ];
const map = {}; let masked = text; const c = {};
for (const [k, re] of rules) masked = masked.replace(re, m => { c[k]=(c[k]||0)+1; const t=`[${k}_${c[k]}]`; map[t]=m; return t; });

return [{ json: { user, dept, depts, text, masked, map, pii_found: Object.keys(map).length } }];

// Odmaskowanie odpowiedzi + przygotowanie wpisu do logu
const src = $('Code: rola + maskowanie PII').first().json;
let answer = String($input.first().json.output || '');
for (const [t, v] of Object.entries(src.map)) answer = answer.split(t).join(v);
return [{ json: { ts: new Date().toISOString(), user: src.user, dept: src.dept, prompt_masked: src.masked, pii_found: src.pii_found, answer } }];
